import Link from "next/link";
import {notFound} from "next/navigation";
import {eq,sql} from "drizzle-orm";
import {db} from "@/db";
import {rankedChallengeItems,rankedChallengeRuns,rankedChallenges} from "@/db/schema";
import {AdminNav} from "@/components/admin/admin-nav";
import {requireAdmin} from "@/lib/admin/authorization";
import {getPreferences} from "@/lib/i18n/get-translations";
import {CHALLENGE_POLICY,challengePhase} from "@/lib/challenges/policy";
import type {ChallengeType} from "@/lib/gamification/catalog";
import {cancelChallengeAction,generateFormAction,publishChallengeAction} from "../actions";
const phaseLabel={DRAFT:"Bản nháp",UPCOMING:"Đã lên lịch",LIVE:"Đang diễn ra",CLOSED:"Đã kết thúc",CANCELLED:"Đã hủy"};
export default async function Page({params,searchParams}:{params:Promise<{id:string}>;searchParams:Promise<{error?:string}>}){const actor=await requireAdmin("CHALLENGE_MANAGE");const p=await getPreferences(actor.id);const vi=p.interfaceLanguage==="vi";const[{id},q]=await Promise.all([params,searchParams]);const[c]=await db.select().from(rankedChallenges).where(eq(rankedChallenges.id,id)).limit(1);if(!c)notFound();const [composition,[{runs}]]=await Promise.all([db.select({part:rankedChallengeItems.part,questions:sql<number>`count(*)::int`,groups:sql<number>`count(distinct ${rankedChallengeItems.groupId})::int`}).from(rankedChallengeItems).where(eq(rankedChallengeItems.challengeId,id)).groupBy(rankedChallengeItems.part),db.select({runs:sql<number>`count(*)::int`}).from(rankedChallengeRuns).where(eq(rankedChallengeRuns.challengeId,id))]);const total=composition.reduce((n,x)=>n+Number(x.questions),0);const policy=CHALLENGE_POLICY[c.type as ChallengeType];const valid=total===policy.questions;const phase=challengePhase(c);return <main className="min-h-screen bg-slate-50 px-4 py-6 sm:px-6"><div className="mx-auto max-w-6xl"><AdminNav locale={p.interfaceLanguage}/><div className="mx-auto mt-8 max-w-3xl"><Link href="/admin/challenges" className="text-sm font-bold text-teal-700">← {vi?"Sự kiện xếp hạng":"Ranking events"}</Link><article className="mt-4 rounded-3xl border bg-white p-6 sm:p-8"><h1 className="text-3xl font-black">{vi?c.titleVi:c.titleEn}</h1><p className="mt-2 text-slate-600">{vi?"Trạng thái":"Status"}: <strong>{vi?phaseLabel[phase]:phase}</strong> · {runs} {vi?"lượt tham gia":"attempts"}</p>{q.error&&<p role="alert" className="mt-5 rounded-xl bg-amber-50 p-4">{vi?"Thao tác chưa hoàn tất. Kiểm tra ngân hàng câu hỏi, lịch và trạng thái sự kiện rồi thử lại.":"Action failed. Check question readiness, schedule, and event status, then retry."}</p>}<section className="mt-7"><h2 className="text-xl font-bold">{vi?"Thông tin người học sẽ thấy":"Learner preview"}</h2><dl className="mt-3 grid gap-3 rounded-xl bg-slate-50 p-5 sm:grid-cols-2"><div><dt className="text-sm text-slate-500">Tiếng Việt</dt><dd className="font-semibold">{c.titleVi}</dd></div><div><dt className="text-sm text-slate-500">English</dt><dd className="font-semibold">{c.titleEn}</dd></div><div><dt className="text-sm text-slate-500">{vi?"Thời gian (GMT+7)":"Schedule (GMT+7)"}</dt><dd>{c.startsAt?.toLocaleString(vi?"vi-VN":"en-US",{timeZone:"Asia/Ho_Chi_Minh"})} – {c.endsAt?.toLocaleString(vi?"vi-VN":"en-US",{timeZone:"Asia/Ho_Chi_Minh"})}</dd></div><div><dt className="text-sm text-slate-500">{vi?"Thể lệ":"Rules"}</dt><dd>{c.type==="READING_100"?"Reading":c.type==="LISTENING_100"?"Listening":"Listening + Reading"} · {policy.questions} {vi?"câu":"questions"} · {policy.durationMs/60000} {vi?"phút":"minutes"} · {vi?"một lượt/người":"one attempt/person"}</dd></div></dl><p className="mt-3 text-sm text-slate-600">{vi?"Điểm sự kiện là số câu đúng, tách biệt RP và bảng xếp hạng tuần. Chỉ người học đăng nhập mới có thể bắt đầu.":"Event score is correct answers, separate from weekly RP. Signed-in learners can start."}</p></section><section className="mt-7"><h2 className="text-xl font-bold">{vi?"Đề đã tạo":"Generated test"}</h2><p className="mt-2">{total}/{policy.questions} {vi?"câu":"questions"} · {valid?(vi?"Đủ số câu":"Question count ready"):(vi?"Chưa đủ số câu":"Question count incomplete")}</p><ul className="mt-2 flex flex-wrap gap-2">{composition.map(x=><li key={x.part} className="rounded-lg bg-slate-100 px-3 py-2 text-sm">Part {x.part}: {x.questions} {vi?"câu":"questions"}</li>)}</ul></section>{c.status==="DRAFT"?<div className="mt-8 grid gap-4 border-t pt-6"><p className="text-sm text-slate-600">{vi?"Bước 1: Tạo đề từ học liệu đã xuất bản. Bước 2: Kiểm tra thông tin và số câu. Bước 3: Công bố; nếu giờ bắt đầu ở tương lai, sự kiện sẽ tự chuyển sang đang diễn ra đúng giờ.":"1. Generate from published content. 2. Review details and question count. 3. Publish; a future start will become live automatically."}</p><form action={generateFormAction.bind(null,id)}><button className="rounded-xl border px-4 py-3 font-bold focus-visible:outline-2">{vi?"Tạo lại đề":"Generate test"}</button></form><form action={publishChallengeAction.bind(null,id)}><label className="mb-3 flex items-start gap-2 text-sm"><input className="mt-1" type="checkbox" required name="reviewed"/><span>{vi?"Tôi đã kiểm tra tên, thời gian, loại đề và số câu. Sau khi công bố không thể sửa đề hoặc lịch.":"I reviewed the titles, schedule, test type, and question count. The test and schedule cannot be edited after publishing."}</span></label><button className="rounded-xl bg-teal-700 px-5 py-3 font-bold text-white disabled:opacity-50" disabled={!valid}>{vi?"Công bố sự kiện":"Publish event"}</button></form></div>:c.status==="PUBLISHED"?<section className="mt-8 border-t pt-6"><p className="text-sm text-slate-600">{vi?"Sự kiện đã công bố không thể sửa. Hủy sẽ dừng lượt mới; hãy cân nhắc tác động đến người đã tham gia.":"Published events cannot be edited. Cancellation stops new attempts and affects existing participants."}</p><details className="mt-4 rounded-xl border border-red-200 p-4"><summary className="cursor-pointer font-bold text-red-700">{vi?"Tùy chọn hủy sự kiện":"Cancel event options"}</summary><form action={cancelChallengeAction.bind(null,id)} className="mt-4"><label className="flex gap-2 text-sm"><input type="checkbox" required name="confirm"/>{vi?"Tôi hiểu việc hủy sự kiện ảnh hưởng đến người học.":"I understand cancellation affects learners."}</label><button className="mt-3 rounded-xl bg-red-700 px-4 py-3 font-bold text-white">{vi?"Xác nhận hủy":"Confirm cancellation"}</button></form></details></section>:null}</article></div></div></main>}
